local function hasFileSystemSupport()
    local hasWritefile = pcall(function() return type(writefile) == "function" end)
    local hasReadfile = pcall(function() return type(readfile) == "function" end)
    return hasWritefile and hasReadfile
end

local fileSystemSupported = hasFileSystemSupport()
local SCRIPT_KEY = nil

local function SavePersistentData()
    if not fileSystemSupported then return false end
    local data = {
        key = SCRIPT_KEY
    }
    pcall(function() writefile("veneno_hub_key_data.json", HttpService:JSONEncode(data)) end)
    return true
end

local function ClearPersistentData()
    if not fileSystemSupported then return false end
    pcall(function() writefile("veneno_hub_key_data.json", HttpService:JSONEncode({key = nil})) end)
    SCRIPT_KEY = nil
    getgenv().SCRIPT_KEY = nil
    return true
end

local function LoadPersistentData()
    if not fileSystemSupported then return false end
    local success, data = pcall(function()
        return HttpService:JSONDecode(readfile("veneno_hub_key_data.json"))
    end)
    if success and data and data.key then
        SCRIPT_KEY = data.key
        getgenv().SCRIPT_KEY = data.key
        return true
    end
    return false
end

local cachedIsMobile = nil
local function IsMobile()
    if cachedIsMobile == nil then
        cachedIsMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
    end
    return cachedIsMobile
end

local cachedViewport = nil
local function GetViewportSize()
    if cachedViewport then return cachedViewport end
    local camera = workspace.CurrentCamera
    if camera then
        cachedViewport = camera.ViewportSize
    else
        cachedViewport = Vector2.new(1280,720)
    end
    return cachedViewport
end

if workspace.CurrentCamera then
    workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
        cachedViewport = workspace.CurrentCamera.ViewportSize
    end)
end

local function GetScaledKeyPanelSize()
    local viewport = GetViewportSize()
    local isMobile = IsMobile()
    local width = isMobile and math.min(300, viewport.X - 40) or 380
    local height = isMobile and math.min(340, viewport.Y - 80) or 420
    return width, height
end

LoadPersistentData()

local keyIsValid = false

if SCRIPT_KEY then
    local checkResult = Junkie.check_key(SCRIPT_KEY)
    if checkResult and checkResult.valid then
        keyIsValid = true
        getgenv().VENENO_KEY = SCRIPT_KEY
        getgenv().SCRIPT_KEY = SCRIPT_KEY
    else
        ClearPersistentData()
    end
else
    ClearPersistentData()
end

