        local function shakeInput()
            if IsMobile() then return end
            local orig = inputSection.Position
            for i = 1, 3 do
                TweenService:Create(inputSection, TweenInfo.new(0.05), {Position = UDim2.new(orig.X.Scale, orig.X.Offset - 5, orig.Y.Scale, orig.Y.Offset)}):Play()
                task.wait(0.05)
                TweenService:Create(inputSection, TweenInfo.new(0.05), {Position = UDim2.new(orig.X.Scale, orig.X.Offset + 5, orig.Y.Scale, orig.Y.Offset)}):Play()
                task.wait(0.05)
            end
            inputSection.Position = orig
        end
        
        local function setButtonLoading(button, text, loading)
            if loading then
                button.Text = "..."
