            if key == "" then
                updateStatus("Please enter a key", true)
                shakeInput()
                return
            end
            
            setButtonLoading(verifyBtn, "VERIFY", true)
            keyInput.Interactable = false
            
            local result = Junkie.check_key(key)
            
            if result and result.valid then
                SCRIPT_KEY = key
                getgenv().SCRIPT_KEY = key
                SavePersistentData()
                updateStatus("Key verified! Loading hub...", false)
                
                if not IsMobile() then
