            end
            container.BackgroundTransparency = 1
            TweenService:Create(container, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {BackgroundTransparency = 0.15}):Play()
            backdrop.BackgroundTransparency = 1
            TweenService:Create(backdrop, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {BackgroundTransparency = 0.5}):Play()
        end
        
