local cachedIsMobileDevice = nil
local function IsMobileDevice()
    if cachedIsMobileDevice == nil then
        cachedIsMobileDevice = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
    end
    return cachedIsMobileDevice
end

local function GetUSEasternUnixTime()
    local utcTable = os.date("!*t")
    local year = utcTable.year
    local function nthSundayOfMonth(ty, m, n)
        local fd = os.time({year=ty, month=m, day=1, hour=12})
        local fw = tonumber(os.date("!*t", fd).wday) or 1
        local fs = 1 + ((1 - fw) % 7)
        return fs + ((n - 1) * 7)
    end
    local ms = nthSundayOfMonth(year,3,2)
    local ns = nthSundayOfMonth(year,11,1)
    local dstStart = os.time({year=year, month=3, day=ms, hour=7})
    local dstEnd = os.time({year=year, month=11, day=ns, hour=6})
    local nowUtc = os.time(utcTable)
    local off = (nowUtc >= dstStart and nowUtc < dstEnd) and -4 or -5
    return nowUtc + (off * 3600)
end

local function GetGreetingText(dn)
    local eh = tonumber(os.date("!*t", GetUSEasternUnixTime()).hour) or 12
    if eh >=5 and eh<12 then return "Good morning, "..dn
    elseif eh>=12 and eh<18 then return "Good afternoon, "..dn
    elseif eh>=18 and eh<24 then return "Good evening, "..dn end
    return "It is late. Go get some sleep, "..dn
end

local executorCache = nil
local function GetExecutorName()
    if executorCache then return executorCache end
    local n = "Unknown"
    pcall(function() n = (identifyexecutor or getexecutorname or function() return "Unknown" end)() end)
    executorCache = n
    return n
end

local restrictedExecutorCache = nil
local function IsRestrictedExecutor()
    if restrictedExecutorCache ~= nil then return restrictedExecutorCache end
    local n = GetExecutorName():lower()
    restrictedExecutorCache = string.find(n, "xeno") ~= nil or string.find(n, "solara") ~= nil
    return restrictedExecutorCache
end

local xenoOrSolaraCache = nil
local function IsXenoOrSolara()
    if xenoOrSolaraCache ~= nil then return xenoOrSolaraCache end
    local n = GetExecutorName():lower()
    xenoOrSolaraCache = string.find(n, "xeno") ~= nil or string.find(n, "solara") ~= nil
    return xenoOrSolaraCache
end

local function SafeHttpGet(url)
    local req = (syn and syn.request) or (http and http.request) or http_request or request or (fluxus and fluxus.request)
    if req then
        local s,r = pcall(function() return req({Url=url, Method="GET"}) end)
        if s and r and r.Body then return r.Body end
    end
    local s,r = pcall(function() return game:HttpGet(url) end)
    if s then return r end
    return nil
end

local function DecodeJson(r)
    if not r or r=="" then return nil end
    local s,d = pcall(function() return HttpService:JSONDecode(r) end)
    if s then return d end
    return nil
end

