local function ApplySoftGlow(frame, color)
    frame.ClipsDescendants = false
    local g = Instance.new("UIGradient", frame)
    g.Color = ColorSequence.new({ColorSequenceKeypoint.new(0,color), ColorSequenceKeypoint.new(1,CardColor)})
    g.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0,0), NumberSequenceKeypoint.new(0.6,0.8), NumberSequenceKeypoint.new(1,1)})
    g.Rotation = -45
    local s = Instance.new("UIStroke", frame)
    s.Color = color
    s.Thickness = 2
    s.Transparency = 0.2
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    s.LineJoinMode = Enum.LineJoinMode.Round
    local p = Instance.new("UIPadding", frame)
    p.PaddingLeft = UDim.new(0,1)
    p.PaddingRight = UDim.new(0,1)
    p.PaddingTop = UDim.new(0,1)
    p.PaddingBottom = UDim.new(0,1)
end

