local function SetupToggleKeyConnection()
    if currentInputConnection then currentInputConnection:Disconnect() end
    currentInputConnection = UserInputService.InputBegan:Connect(function(inp, gp)
        if not gp and inp.KeyCode == CurrentToggleKey then
            if MainFrame.Visible then
                savedPosition = MainFrame.Position
                PanelPosition = Vector2.new(MainFrame.Position.X.Offset, MainFrame.Position.Y.Offset)
                PanelHasCustomPosition = true
                if not IsMobileDevice() then
                    TweenService:Create(MainFrame, TweenInfo.new(0.2), {BackgroundTransparency=0.5}):Play()
                    task.wait(0.1)
                end
                MainFrame.Visible = false
                MainFrame.BackgroundTransparency = 0.05
            else
                MainFrame.Visible = true
                if savedPosition then
                    MainFrame.Position = savedPosition
                    PanelPosition = Vector2.new(savedPosition.X.Offset, savedPosition.Y.Offset)
                    PanelHasCustomPosition = true
                else
                    local vp = GetViewportSize()
                    local ct = UDim2.fromOffset(math.floor((vp.X - MainFrame.AbsoluteSize.X)*0.5), math.floor((vp.Y - MainFrame.AbsoluteSize.Y)*0.5))
                    MainFrame.Position = ct
                    PanelPosition = Vector2.new(ct.X.Offset, ct.Y.Offset)
                    PanelHasCustomPosition = false
                end
                MainFrame.BackgroundTransparency = 0.5
                if not IsMobileDevice() then
                    TweenService:Create(MainFrame, TweenInfo.new(0.3), {BackgroundTransparency=0.05}):Play()
                else
                    MainFrame.BackgroundTransparency = 0.05
                end
            end
        end
    end)
end

