local chests = {}
local cashRegisters = {}
local registerCooldowns = {}
local currentCityIndex = 1
local currentBankIndex = 1
local cycleCooldown = 40
local lastCycleTime = 0
local registerCooldownTime = 90
local safeZone = CFrame.new(1636.62537, 104.349976, -1736.184)
local lastCacheUpdate = 0
local cacheUpdateInterval = 0.2
local cacheInterval = 0.3

local bankThread = nil
local cashThread = nil
local chestThread = nil
local bypassConnection = nil

