local isDead = false
local isRespawning = false
local respawnThread = nil

local function stopAutoRespawn()
    if respawnThread then
        task.cancel(respawnThread)
        respawnThread = nil
    end
    isDead = false
    isRespawning = false
end

local function startAutoRespawn()
    if respawnThread then return end
    isDead = false
    isRespawning = false
    respawnThread = task.spawn(function()
        while true do
            if isDead and not isRespawning then
                isRespawning = true
                task.wait(1)
                if isDead then
                    pcall(function()
                        SpawnEvent:InvokeServer(nil, false)
                    end)
                end
                isRespawning = false
            end
            task.wait(0.1)
        end
    end)
end

local function onCharacterRemoving()
    isDead = true
    isRespawning = false
end

local function onCharacterAdded(newChar)
    isDead = false
    isRespawning = false
    character = newChar
    humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
    task.wait(0.2)
end

LocalPlayer.CharacterRemoving:Connect(onCharacterRemoving)
LocalPlayer.CharacterAdded:Connect(onCharacterAdded)

startAutoRespawn()

local function teleportToPosition(pos)
    if not humanoidRootPart then return end
    humanoidRootPart.CFrame = CFrame.new(pos)
    task.wait(0.05)
end

local function instaTeleport(pos)
    local root = character:FindFirstChild("HumanoidRootPart")
    if root then
        root.CFrame = typeof(pos) == "Vector3" and CFrame.new(pos) or pos
        return true
    end
    return false
end

local function findSafesAtPosition(pos)
    local safes = {}
    for _, obj in pairs(Workspace:GetChildren()) do
        if obj:IsA("Model") and obj.Name == "Safe" then
            local safePos = obj:GetPivot().Position
            local dist = (safePos - pos).Magnitude
            if dist < 500 then
                local amount = obj:FindFirstChild("Amount")
                if amount and amount.Value > 0 then
                    table.insert(safes, obj)
                end
            end
        end
    end
    return safes
end

local function openAndRobSafe(safe)
    local openEvent = safe:FindFirstChild("OpenSafe")
    if openEvent then
        pcall(function() openEvent:FireServer("Complete") end)
        task.wait(0.05)
        pcall(function() RobEvent:FireServer("Safe", safe) end)
        return true
    end
    return false
end

local function isBagFull()
    if bag and bagLimit then
        return bag.Value >= bagLimit.Value
    end
    return false
end

local function cashOutMoney()
    if not bag then return end
    if bag.Value == 0 then return end
    teleportToPosition(outlawRescuePos)
    task.wait(1)
end

local function farmBank(bank)
    bank.robbedCount = 0
    while bank.robbedCount < bank.totalSafes and getgenv().BankFarmActive do
        teleportToPosition(bank.insidePos)
        local safes = findSafesAtPosition(bank.insidePos)
        local robbed = false
        for _, safe in pairs(safes) do
            if not getgenv().BankFarmActive then break end
            if bank.robbedCount >= bank.totalSafes then break end
            if openAndRobSafe(safe) then
                bank.robbedCount = bank.robbedCount + 1
                robbed = true
                if isBagFull() then
                    cashOutMoney()
                    task.wait(2)
                    teleportToPosition(bank.insidePos)
                end
                task.wait(0.1)
                break
            end
        end
        if not robbed then break end
        task.wait(0.2)
    end
end

local function bankLoop()
    while getgenv().BankFarmActive do
        for i = 1, #banks do
            if not getgenv().BankFarmActive then break end
            currentBankIndex = i
            farmBank(banks[i])
        end
        task.wait(1)
    end
end

local function updateCaches()
    if tick() - lastCacheUpdate < cacheUpdateInterval then
        return #cashRegisters
    end
    lastCacheUpdate = tick()
    cashRegisters = {}
    for _, child in pairs(Workspace:GetChildren()) do
        if child:IsA("Model") and child.Name == "CashRegister" then
            local active = child:FindFirstChild("Active")
            if active and active.Value then
                table.insert(cashRegisters, child)
            end
        end
    end
    return #cashRegisters
end

local function canRobRegister(reg)
    if not reg then return false end
    local lastRob = registerCooldowns[reg]
    if not lastRob then return true end
    return (tick() - lastRob) >= registerCooldownTime
end

local function markRegisterRobbed(reg)
    registerCooldowns[reg] = tick()
end

local function attemptRegister(reg)
    if not reg or not reg.Parent then return false end
    if not canRobRegister(reg) then return false end
    local openPart = reg:FindFirstChild("Open")
    local union = reg:FindFirstChild("Union")
    local active = reg:FindFirstChild("Active")
    if openPart and union and active and active.Value then
        instaTeleport(openPart.CFrame)
        task.wait(0.2)
        local success = false
        for i = 1, 5 do
            local s = pcall(function()
                RobEvent:FireServer("Register", {
                    Part = union,
                    OpenPart = openPart,
                    ActiveValue = active,
                    Active = true
                })
            end)
            if s then success = true end
            task.wait(0.05)
        end
        if success then
            markRegisterRobbed(reg)
            return true
        end
    end
    return false
end

local function farmCity(cityIndex)
    local city = cities[cityIndex]
    if not city then return false end
    instaTeleport(city.spawn)
    task.wait(2)
    updateCaches()
    for _, reg in ipairs(cashRegisters) do
        if not getgenv().CashFarmActive then return false end
        if bag and bagLimit and bag.Value >= bagLimit.Value then
            instaTeleport(safeZone)
            task.wait(1)
        end
        attemptRegister(reg)
        task.wait(0.1)
    end
    return true
end

local function cashLoop()
    while getgenv().CashFarmActive do
        pcall(function()
            if tick() - lastCycleTime >= cycleCooldown then
                currentCityIndex = 1
            end
            if currentCityIndex <= #cities then
                farmCity(currentCityIndex)
                currentCityIndex = currentCityIndex + 1
            else
                currentCityIndex = 1
                lastCycleTime = tick()
                task.wait(2)
            end
        end)
        task.wait(0.1)
    end
end

local function updateCache()
    if tick() - lastCacheUpdate < cacheInterval then
        return #chests
    end
    lastCacheUpdate = tick()
    chests = {}
    local folder = Workspace:FindFirstChild("ChestFolder")
    if folder then
        for _, c in ipairs(folder:GetChildren()) do
            if c:IsA("Model") and c.Name == "TreasureChest" then
                local opened = c:FindFirstChild("Opened")
                if not opened or opened.Value == false then
                    table.insert(chests, c)
                end
            end
        end
    end
    return #chests
end

local folder = Workspace:FindFirstChild("ChestFolder")
if folder then
    folder.ChildAdded:Connect(function(c)
        if c:IsA("Model") and c.Name == "TreasureChest" then
            local opened = c:FindFirstChild("Opened")
            if not opened or opened.Value == false then
                table.insert(chests, c)
            end
        end
    end)
    folder.ChildRemoved:Connect(function(c)
        if c:IsA("Model") and c.Name == "TreasureChest" then
            for i = #chests, 1, -1 do
                if chests[i] == c then
                    table.remove(chests, i)
                end
            end
        end
    end)
end

local function openChest(c)
    if not c or not c.Parent then return false end
    if not RobEvent then return false end
    local part = c:FindFirstChild("Chest") or c.PrimaryPart
    if not part then return false end
    instaTeleport(part.CFrame * CFrame.new(0, 2, 0))
    task.wait(0.2)
    local success = false
    for i = 1, 3 do
        local s = pcall(function()
            RobEvent:FireServer("TreasureChest", c)
        end)
        if s then success = true end
        task.wait(0.05)
    end
    return success
end

local function chestLoop()
    while getgenv().ChestFarmActive do
        pcall(function()
            updateCache()
            for _, c in ipairs(chests) do
                if not getgenv().ChestFarmActive then break end
                openChest(c)
                task.wait(0.1)
            end
            task.wait(0.5)
        end)
        task.wait(0.1)
    end
end

local function antiDeath(char)
    pcall(function()
        local hum = char:FindFirstChildWhichIsA("Humanoid")
        if not hum then return end
        local cloned = hum:Clone()
        cloned.Parent = char
        cloned.RigType = Enum.HumanoidRigType.R6
        cloned:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
        cloned:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        cloned:SetStateEnabled(Enum.HumanoidStateType.Physics, false)
        local animClone = cloned:FindFirstChild("Animator")
        if animClone then animClone:Destroy() end
        LocalPlayer.Character = nil
        hum:Destroy()
        LocalPlayer.Character = char
        local animate = char:FindFirstChild("Animate")
        if animate then
            animate.Disabled = true
            task.wait(0.1)
            animate.Disabled = false
        end
        local cam = workspace.CurrentCamera
        if cam then
            cam.CameraSubject = cloned
        end
        cloned.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
        cloned.Health = cloned.MaxHealth
    end)
end

local function startBypass()
    if getgenv().BypassActive then return end
    getgenv().BypassActive = true
    local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    antiDeath(char)
    if bypassConnection then bypassConnection:Disconnect() end
    bypassConnection = LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.wait(0.15)
        if getgenv().BypassActive then
            antiDeath(newChar)
        end
    end)
end

local function stopBypass()
    getgenv().BypassActive = false
    if bypassConnection then
        bypassConnection:Disconnect()
        bypassConnection = nil
    end
end

local function monitorMoney()
    if moneyStat then
        local current = moneyStat.Value
        if current > lastMoneyValue then
            getgenv().SHARED_TOTAL_MONEY = getgenv().SHARED_TOTAL_MONEY + (current - lastMoneyValue)
            lastMoneyValue = current
        end
    end
end

if moneyStat then
    moneyStat:GetPropertyChangedSignal("Value"):Connect(monitorMoney)
end

local function stopAllFarms()
    getgenv().BankFarmActive = false
    getgenv().CashFarmActive = false
    getgenv().ChestFarmActive = false
    if bankThread then task.cancel(bankThread) bankThread = nil end
    if cashThread then task.cancel(cashThread) cashThread = nil end
    if chestThread then task.cancel(chestThread) chestThread = nil end
    stopBypass()
end

local activationTimer = nil

local function startAllFarms()
    if getgenv().CashFarmActive or getgenv().ChestFarmActive or getgenv().BankFarmActive then return end
    if activationTimer then return end
    if getgenv().SHARED_FARM_START_TIME == 0 then
        getgenv().SHARED_FARM_START_TIME = tick()
        lastMoneyValue = moneyStat and moneyStat.Value or 0
    end
    startBypass()
    activationTimer = task.spawn(function()
        task.wait(5)
        getgenv().CashFarmActive = true
        currentCityIndex = 1
        lastCycleTime = tick()
        if cashThread == nil then
            cashThread = task.spawn(cashLoop)
        end
        task.wait(5)
        getgenv().ChestFarmActive = true
        updateCache()
        if chestThread == nil then
            chestThread = task.spawn(chestLoop)
        end
        task.wait(5)
        getgenv().BankFarmActive = true
        if bankThread == nil then
            bankThread = task.spawn(bankLoop)
        end
        activationTimer = nil
    end)
end

local function formatTime(seconds)
    local hours = math.floor(seconds / 3600)
    local mins = math.floor((seconds % 3600) / 60)
    local secs = math.floor(seconds % 60)
    return string.format("%02d:%02d:%02d", hours, mins, secs)
end

