                "Bed", "BigWindow", "BlackTunnel", "Door", "HingeDoor", 
                "JailCell", "LAMP", "Lamp", "Line", "MineEntrace", "MansionClosed", "Window", 
                "Barrel", "Crate", "DeadBush", "DeadTree", "TelephonePole", "Bottle", 
                "Table", "Fence"
            }
            for _, v in pairs(Workspace:GetDescendants()) do
                if table.find(modelsToRemove, v.Name) and not v:IsA("SpawnLocation") then
                    v:Destroy()
                end
            end
            for _, effect in pairs(Lighting:GetChildren()) do
                if effect:IsA("PostEffect") or effect:IsA("BloomEffect") or effect:IsA("BlurEffect") or effect:IsA("SunRaysEffect") then
                    effect.Enabled = false
                end
            end
            Terrain.Decoration = false
            Terrain.WaterWaveSize = 0
            Terrain.WaterWaveSpeed = 0
            Terrain.WaterReflectance = 0
            Terrain.WaterTransparency = 0
            settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
            Lighting.GlobalShadows = false
            Lighting.Brightness = 1
            for _, v in pairs(Workspace:GetDescendants()) do
                if v:IsA("Part") or v:IsA("MeshPart") or v:IsA("BasePart") then
                    if not v:IsA("SpawnLocation") then
                        v.Material = Enum.Material.SmoothPlastic
                        v.Reflectance = 0
                    end
                elseif v:IsA("Decal") or v:IsA("Texture") then
                    v.Transparency = 1
                elseif v:IsA("ParticleEmitter") or v:IsA("Trail") then
                    v.Enabled = false
                end
            end
            ShowNotification("BOOST FPS", "ACTIVATED!", 3)
            return
        end
        if name == "TREASURE CHEST" or name == "CASH REGISTER" then
            if executed then
                ShowNotification("ALREADY ACTIVE", "THIS FUNCTION IS ALREADY ACTIVATED", 3)
                return
            end
            executed = true
            active = true
            ApplyActive()
            pcall(function()
                if scriptUrl then
                    loadstring(game:HttpGet(scriptUrl))()
                end
            end)
            ShowNotification(name, "ACTIVATED! IF YOU DID NOT ACTIVATE INSTANT RESPAWN, ACTIVATE IT", 5)
            return
        end
        if name == "ROB ALL PLAYERS" then
            if executed then
                ShowNotification("ALREADY ACTIVE", "THIS FUNCTION IS ALREADY ACTIVATED", 3)
                return
            end
            executed = true
            active = true
            ApplyActive()
            pcall(function()
                if scriptUrl then
                    loadstring(game:HttpGet(scriptUrl))()
                end
            end)
