        end
        if restricted[name] and IsRestrictedExecutor() then
            ShowNotification("BLOCKED", "THIS EXECUTOR DOES NOT SUPPORT THESE SCRIPTS", 3)
            return
        end
        if isPermanent and executed then
            ShowNotification("ALREADY ACTIVE", "THIS FUNCTION IS ALREADY ACTIVATED", 3)
            return
        end
        if needDoubleConfirm and not active and not confirmStep and not executed then
            confirmStep = true
            if name == "WALKSPEED" then
                ShowNotification("CONFIRMATION", "THIS FUNCTION CONFLICTS WITH YOUR HORSE", 4)
            else
                ShowNotification("CONFIRMATION", "MAY CONFLICT WITH OTHER FUNCTIONS", 4)
            end
            task.wait(0.5)
            confirmStep = false
            return
        end
        if isPermanent and not executed then
            executed = true
            active = true
            ApplyActive()
            pcall(function()
                if scriptUrl then
                    loadstring(game:HttpGet(scriptUrl))()
                end
            end)
