                        if myTeam == Teams.Cowboys and targetTeam == Teams.Cowboys then return false end
                        return true
                    end
                    local function findThrownDynamite()
                        for _, obj in pairs(workspace:GetChildren()) do
                            if obj:IsA("BasePart") and obj.Name == "DynamitePart" then
                                if not activeDynamites[obj] then
                                    local humanoidRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
