local bypassActive = false

local function CreateFarmToggle(parent, name, scriptUrl, customMessage)
    local tf = Instance.new("Frame", parent)
    tf.Size = UDim2.new(1,0,0,45)
    tf.BackgroundColor3 = Color3.fromRGB(30,30,40)
    tf.BackgroundTransparency = 0.4
    Instance.new("UICorner", tf).CornerRadius = UDim.new(0,8)
    local ts = Instance.new("UIStroke", tf)
    ts.Color = CurrentTheme
    ts.Thickness = 1
    ts.Transparency = 0.5
    local title = Instance.new("TextLabel", tf)
    title.Size = UDim2.new(1,-60,1,0)
    title.Position = UDim2.new(0,15,0,0)
    title.Text = name
    title.TextColor3 = Color3.fromRGB(230,230,230)
    title.Font = Enum.Font.GothamMedium
    title.TextSize = 13
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.BackgroundTransparency = 1
    local sw = Instance.new("TextButton", tf)
    sw.Size = UDim2.new(0,38,0,20)
    sw.Position = UDim2.new(1,-50,0.5,-10)
    sw.BackgroundColor3 = Color3.fromRGB(60,60,75)
    sw.Text = ""
    Instance.new("UICorner", sw).CornerRadius = UDim.new(1,0)
    local circ = Instance.new("Frame", sw)
    circ.Size = UDim2.new(0,14,0,14)
    circ.Position = UDim2.new(0,3,0.5,-7)
    circ.BackgroundColor3 = Color3.fromRGB(200,200,200)
    Instance.new("UICorner", circ).CornerRadius = UDim.new(1,0)
    local active = false
    local function ApplyActive()
        if not IsMobileDevice() then
            TweenService:Create(sw, TweenInfo.new(0.2), {BackgroundColor3=CurrentTheme}):Play()
            TweenService:Create(circ, TweenInfo.new(0.2), {Position=UDim2.new(1,-17,0.5,-7), BackgroundColor3=Color3.new(1,1,1)}):Play()
        else
            sw.BackgroundColor3 = CurrentTheme
            circ.Position = UDim2.new(1,-17,0.5,-7)
            circ.BackgroundColor3 = Color3.new(1,1,1)
        end
    end
    local function ApplyInactive()
        if not IsMobileDevice() then
            TweenService:Create(sw, TweenInfo.new(0.2), {BackgroundColor3=Color3.fromRGB(60,60,75)}):Play()
            TweenService:Create(circ, TweenInfo.new(0.2), {Position=UDim2.new(0,3,0.5,-7), BackgroundColor3=Color3.fromRGB(200,200,200)}):Play()
        else
            sw.BackgroundColor3 = Color3.fromRGB(60,60,75)
            circ.Position = UDim2.new(0,3,0.5,-7)
            circ.BackgroundColor3 = Color3.fromRGB(200,200,200)
        end
    end
    sw.MouseButton1Click:Connect(function()
        if IsRestrictedExecutor() then
            ShowNotification("BLOCKED", "THIS EXECUTOR DOES NOT SUPPORT THESE SCRIPTS", 3)
            return
        end
        if not getgenv().VENENO_BYPASS_ACTIVE then
            ShowNotification("BLOCKED", "ACTIVATE BYPASS ANTI-CHEAT FIRST", 3)
            return
        end
        active = not active
        if active then
            ApplyActive()
            pcall(function()
                if scriptUrl then
                    loadstring(game:HttpGet(scriptUrl))()
                end
            end)
            if customMessage then
                ShowNotification(name, customMessage, 4)
            else
                ShowNotification(name, "ACTIVATED!", 2)
            end
        else
            ApplyInactive()
            ShowNotification(name, "DISABLED", 2)
        end
    end)
    return tf
end

local function CreateTeamButton(parent, name, team)
    local bf = Instance.new("Frame", parent)
