    local title = Instance.new("TextLabel", bf)
    title.Size = UDim2.new(1,-60,1,0)
    title.Position = UDim2.new(0,15,0,0)
    title.Text = name
    title.TextColor3 = Color3.fromRGB(230,230,230)
    title.Font = Enum.Font.GothamMedium
    title.TextSize = 13
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.BackgroundTransparency = 1
    local btn = Instance.new("TextButton", bf)
    btn.Size = UDim2.new(0,60,0,30)
    btn.Position = UDim2.new(1,-70,0.5,-15)
    btn.Text = "JOIN"
    btn.BackgroundColor3 = CurrentTheme
    btn.TextColor3 = Color3.fromRGB(255,255,255)
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 11
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0,6)
    btn.MouseButton1Click:Connect(function()
        pcall(function()
            game.Players.LocalPlayer.Team = team
        end)
        local tn = string.gsub(name, "BECOME ", "")
        ShowNotification("TEAM", "YOU JOINED THE "..tn:upper().." TEAM", 2)
    end)
    return bf
end

