        cp = tostring(p)
    end)
end)
local function FormatRegionText(cc, rn, ct)
    local ccl = (cc and tostring(cc):upper()) or "Unknown"
    local rnl = rn and tostring(rn) or nil
    local ctl = ct and tostring(ct) or nil
    if rnl and rnl~="" and ctl and ctl~="" then
        return ccl.." - "..rnl.." ("..ctl..")"
    elseif rnl and rnl~="" then
        return ccl.." - "..rnl
    end
    return ccl
end
local function ResolveServerRegion()
    local ip = cp and cp:match("(%d+%.%d+%.%d+%.%d+)")
    if ip then
        local pl = DecodeJson(SafeHttpGet("http://ip-api.com/json/"..ip.."?fields=status,countryCode,regionName,city"))
        if pl and pl.status=="success" and pl.countryCode then
            rv.Text = FormatRegionText(pl.countryCode, pl.regionName, pl.city)
            return true
        end
        pl = DecodeJson(SafeHttpGet("https://ipwho.is/"..ip))
        if pl and pl.success~=false and pl.country_code then
            rv.Text = FormatRegionText(pl.country_code, pl.region, pl.city)
            return true
        end
        pl = DecodeJson(SafeHttpGet("https://ipinfo.io/"..ip.."/json"))
        if pl and pl.country then
            rv.Text = FormatRegionText(pl.country, pl.region, pl.city)
            return true
        end
    end
    local s,pc = pcall(function()
        return LocalizationService:GetCountryRegionForPlayerAsync(player)
    end)
    if s and pc and pc~="" then
        rv.Text = tostring(pc):upper()
        return true
    end
    return false
end
task.spawn(function()
    local a = 0
    while a<15 do
        a=a+1
        if ResolveServerRegion() then
            break
        end
        rv.Text = a<15 and "Locating..." or "Unavailable"
        task.wait(2)
    end
end)
