local function ClampPanelToViewport()
    if isPanelDragging then return end
    local vp = GetViewportSize()
    local sz = MainFrame.AbsoluteSize
    local cx = math.clamp(PanelPosition.X, 0, math.max(0, vp.X - sz.X))
    local cy = math.clamp(PanelPosition.Y, 0, math.max(0, vp.Y - sz.Y))
    PanelPosition = Vector2.new(cx,cy)
    PanelHasCustomPosition = true
    MainFrame.AnchorPoint = Vector2.zero
    MainFrame.Position = UDim2.fromOffset(math.floor(cx+0.5), math.floor(cy+0.5))
end
end

