        xaStep = true
        ShowNotification("CONFIRMATION", "ACTIVATE XENO AIMBOT?", 4)
        task.wait(0.5)
        xaStep = false
        return
    end
    xaActive = not xaActive
    if xaActive then
        if not IsMobileDevice() then
            TweenService:Create(xas, TweenInfo.new(0.2), {BackgroundColor3=CurrentTheme}):Play()
            TweenService:Create(xacir, TweenInfo.new(0.2), {Position=UDim2.new(1,-17,0.5,-7), BackgroundColor3=Color3.new(1,1,1)}):Play()
        else
            xas.BackgroundColor3 = CurrentTheme
            xacir.Position = UDim2.new(1,-17,0.5,-7)
            xacir.BackgroundColor3 = Color3.new(1,1,1)
        end
        local aimbotScript = [[
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local localPlayer = Players.LocalPlayer
local camera = workspace.CurrentCamera
local settings = { fov = 150, smoothness = 1 }
local aimbotActive = true
local function getPlayerTeam(player)
    if player.Team then
        return player.Team.Name
    end
    return nil
end
local function canTarget(player)
    local localTeam = getPlayerTeam(localPlayer)
    local targetTeam = getPlayerTeam(player)
    if not localTeam or not targetTeam then
        return false
    end
    if targetTeam == "Civilians" then
        return false
    end
    if localTeam == "Cowboys" then
        return targetTeam == "Outlaws"
    elseif localTeam == "Outlaws" then
        return targetTeam == "Cowboys" or targetTeam == "Outlaws"
    elseif localTeam == "Civilians" then
        return false
    end
    return false
end
local function isVisible(character, part)
    local origin = camera.CFrame.Position
    local ray = Ray.new(origin, (part.Position - origin).Unit * (part.Position - origin).Magnitude)
    local hit = workspace:FindPartOnRay(ray, localPlayer.Character)
    if hit then
        local hitParent = hit.Parent
        while hitParent do
            if hitParent == character then
                return true
            end
            hitParent = hitParent.Parent
        end
        return false
    end
    return true
end
local function getClosestPlayer()
    local localChar = localPlayer.Character
    if not localChar then
        return nil
    end
    local localPos = localChar:FindFirstChild("HumanoidRootPart")
    if not localPos then
        return nil
    end
    local closest = nil
    local shortestDist = math.huge
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= localPlayer and player.Character and canTarget(player) then
            local targetChar = player.Character
            local targetPos = targetChar:FindFirstChild("HumanoidRootPart")
            if targetPos then
                local dist = (localPos.Position - targetPos.Position).Magnitude
                if dist < shortestDist then
                    shortestDist = dist
                    closest = player
                end
            end
        end
    end
    return closest
end
RunService.RenderStepped:Connect(function()
    if not aimbotActive then
        return
    end
    if not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
        return
    end
    local closestPlayer = getClosestPlayer()
    if not closestPlayer or not closestPlayer.Character then
        return
    end
    local head = closestPlayer.Character:FindFirstChild("Head")
    if not head then
        return
    end
    if not isVisible(closestPlayer.Character, head) then
        return
    end    local screenPos, onScreen = camera:WorldToViewportPoint(head.Position)
    if not onScreen then
        return
    end
    local mousePos = UserInputService:GetMouseLocation()
    local distance = (Vector2.new(screenPos.X, screenPos.Y) - mousePos).Magnitude
    if distance <= settings.fov then
        local deltaX = screenPos.X - mousePos.X
        local deltaY = screenPos.Y - mousePos.Y
        mousemoverel(deltaX, deltaY)
    end
end)
]]
        pcall(function()
            loadstring(aimbotScript)()
        end)
        ShowNotification("XENO AIMBOT", "ACTIVATED", 2)
    else
        if not IsMobileDevice() then
            TweenService:Create(xas, TweenInfo.new(0.2), {BackgroundColor3=Color3.fromRGB(60,60,75)}):Play()
            TweenService:Create(xacir, TweenInfo.new(0.2), {Position=UDim2.new(0,3,0.5,-7), BackgroundColor3=Color3.fromRGB(200,200,200)}):Play()
        else
            xas.BackgroundColor3 = Color3.fromRGB(60,60,75)
            xacir.Position = UDim2.new(0,3,0.5,-7)
            xacir.BackgroundColor3 = Color3.fromRGB(200,200,200)
        end
        ShowNotification("XENO AIMBOT", "DISABLED", 2)
    end
end)
end

