local draggingShp = false
local minPlayers = 0
local maxPlayers = 35
local selectedMaxPlayers = 0
local function UpdateShpSlider()
    local fillPercent = (selectedMaxPlayers - minPlayers) / (maxPlayers - minPlayers)
    shpFill.Size = UDim2.new(fillPercent,0,1,0)
    shpBtn.Position = UDim2.new(fillPercent,-8,0,0)
    shpLabel.Text = "MAX PLAYERS: "..selectedMaxPlayers
end
UpdateShpSlider()
local function StartDragShp()
    draggingShp = true
end
local function UpdateDragShp(input)
    if draggingShp then
        local mp = input.Position
        local ap = shpSlider.AbsolutePosition
        local asz = shpSlider.AbsoluteSize
        local rx = math.clamp((mp.X - ap.X) / asz.X, 0, 1)
        local nv = minPlayers + math.floor(rx * (maxPlayers - minPlayers))
        selectedMaxPlayers = nv
        UpdateShpSlider()
    end
end
local function EndDragShp()
    draggingShp = false
end
shpBtn.MouseButton1Down:Connect(StartDragShp)
shpBtn.TouchTap:Connect(StartDragShp)
UserInputService.InputChanged:Connect(function(inp)
    if draggingShp and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
        UpdateDragShp(inp)
    end
end)
UserInputService.InputEnded:Connect(function(inp)
    if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
        EndDragShp()
    end
end)
