        end)
        if success and result and result.data then
            for _, server in pairs(result.data) do
                if server.playing <= selectedMaxPlayers and server.id ~= game.JobId then
                    table.insert(servers, server)
                end
            end
            if #servers > 0 then
                local randomServer = servers[math.random(1, #servers)]
                task.wait(0.5)
                TeleportService:TeleportToPlaceInstance(game.PlaceId, randomServer.id, player)
            else
                ShowNotification("ERROR", "NO SERVERS FOUND WITH "..selectedMaxPlayers.." OR LESS PLAYERS", 3)
            end
        else
            ShowNotification("ERROR", "FAILED TO GET SERVER LIST", 3)
        end
    end)
end)
end

