    ind.BackgroundTransparency = 1
    Instance.new("UICorner", ind).CornerRadius = UDim.new(1,0)
    local bst = Instance.new("UIStroke", btn)
    bst.Color = CurrentTheme
    bst.Thickness = 1.5
    bst.Transparency = 0.6
    local function SetActive(act)
        TabButtons[tn].CurrentlyActive = act
        if act then
            if not IsMobileDevice() then
                TweenService:Create(btn, TweenInfo.new(0.3), {BackgroundColor3=Color3.fromRGB(45,45,60)}):Play()
                TweenService:Create(icon, TweenInfo.new(0.3), {ImageColor3=CurrentTheme}):Play()
                TweenService:Create(ind, TweenInfo.new(0.3), {BackgroundTransparency=0, Size=UDim2.new(0,4,0,20), Position=UDim2.new(0,-8,0.5,-10)}):Play()
                TweenService:Create(bst, TweenInfo.new(0.3), {Transparency=0}):Play()
            else
                btn.BackgroundColor3 = Color3.fromRGB(45,45,60)
                icon.ImageColor3 = CurrentTheme
                ind.BackgroundTransparency = 0
                ind.Size = UDim2.new(0,4,0,20)
                ind.Position = UDim2.new(0,-8,0.5,-10)
                bst.Transparency = 0
            end
        else
            if not IsMobileDevice() then
                TweenService:Create(btn, TweenInfo.new(0.3), {BackgroundColor3=Color3.fromRGB(35,35,45)}):Play()
                TweenService:Create(icon, TweenInfo.new(0.3), {ImageColor3=Color3.fromRGB(255,255,255)}):Play()
                TweenService:Create(ind, TweenInfo.new(0.3), {BackgroundTransparency=1, Size=UDim2.new(0,4,0,15), Position=UDim2.new(0,-8,0.5,-7.5)}):Play()
                TweenService:Create(bst, TweenInfo.new(0.3), {Transparency=0.6}):Play()
            else
                btn.BackgroundColor3 = Color3.fromRGB(35,35,45)
                icon.ImageColor3 = Color3.fromRGB(255,255,255)
                ind.BackgroundTransparency = 1
                ind.Size = UDim2.new(0,4,0,15)
                ind.Position = UDim2.new(0,-8,0.5,-7.5)
                bst.Transparency = 0.6
            end
        end
    end
    btn.MouseButton1Click:Connect(function()
        for n,bd in pairs(TabButtons) do
            Pages[n].Visible = false
            bd.Update(false)
        end
        Pages[tn].Visible = true
        SetActive(true)
    end)
    TabButtons[tn] = {Button=btn, Update=SetActive, CurrentlyActive=false}
    return SetActive
end

