local dragStarted = false
local dragStartPos = nil
local dragFramePos = nil
local dragInput = nil
local dragThreshold = false
local function EndDrag()
    dragStarted = false
    dragInput = nil
    dragThreshold = false
    isPanelDragging = false
    PanelHasCustomPosition = true
    task.defer(ClampPanelToViewport)
end
TopBar.InputBegan:Connect(function(inp)
    if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
        dragStarted = true
        dragInput = inp
        dragThreshold = false
        dragStartPos = inp.Position
        dragFramePos = PanelPosition
        PanelHasCustomPosition = true
        isPanelDragging = false
        inp.Changed:Connect(function()
            if inp.UserInputState == Enum.UserInputState.End or inp.UserInputState == Enum.UserInputState.Cancel then
                EndDrag()
            end
        end)
    end
end)
TopBar.InputEnded:Connect(function(inp)
    if inp == dragInput then
        EndDrag()
    end
end)
UserInputService.InputChanged:Connect(function(inp)
    if not dragStarted or not dragInput then
        return
    end
    local vmd = dragInput.UserInputType == Enum.UserInputType.MouseButton1 and inp.UserInputType == Enum.UserInputType.MouseMovement
    local vtd = dragInput.UserInputType == Enum.UserInputType.Touch and inp == dragInput
    if not (vmd or vtd) then
        return
    end
    local delta = inp.Position - dragStartPos
    if not dragThreshold then
        if math.abs(delta.X) < 3 and math.abs(delta.Y) < 3 then
            return
        end
        dragThreshold = true
        isPanelDragging = true
    end
    local vp = GetViewportSize()
    local fsz = MainFrame.AbsoluteSize
    local nx = dragFramePos.X + delta.X
    local ny = dragFramePos.Y + delta.Y
    local cx = math.clamp(nx, 0, math.max(0, vp.X - fsz.X))
    local cy = math.clamp(ny, 0, math.max(0, vp.Y - fsz.Y))
    PanelPosition = Vector2.new(cx,cy)
    PanelHasCustomPosition = true
    MainFrame.AnchorPoint = Vector2.zero
    MainFrame.Position = UDim2.fromOffset(math.floor(cx+0.5), math.floor(cy+0.5))
end)

local isMobile = IsMobileDevice()
local tw = isMobile and 420 or 650
local th = isMobile and 320 or 460
MainFrame.Size = UDim2.fromOffset(tw, th)
MainFrame.BackgroundColor3 = DarkBackground
MainFrame.BackgroundTransparency = 0.05

local function SetPanelToCenter()
    local vp = GetViewportSize()
    local cx = math.max(0, math.floor((vp.X - tw) * 0.5))
    local cy = math.max(0, math.floor((vp.Y - th) * 0.5))
    PanelPosition = Vector2.new(cx,cy)
    PanelHasCustomPosition = false
    MainFrame.AnchorPoint = Vector2.zero
    MainFrame.Position = UDim2.fromOffset(cx,cy)
end

SetPanelToCenter()

