if IsMobileDevice() then
    local ToggleButton = Instance.new("ImageButton")
    ToggleButton.Name = "ToggleButton"
    ToggleButton.Size = UDim2.new(0, 55, 0, 55)
    ToggleButton.Position = UDim2.new(0, 15, 0.5, -27)
    ToggleButton.BackgroundColor3 = Color3.fromRGB(220, 40, 40)
    ToggleButton.BackgroundTransparency = 0
    ToggleButton.Image = "rbxassetid://105731975553006"
    ToggleButton.ImageColor3 = Color3.fromRGB(255, 255, 255)
    ToggleButton.ScaleType = Enum.ScaleType.Fit
    ToggleButton.Parent = ScreenGui
    ToggleButton.ZIndex = 999999999
    
    local btnCorner = Instance.new("UICorner", ToggleButton)
    btnCorner.CornerRadius = UDim.new(0, 12)
    
    local btnStroke = Instance.new("UIStroke", ToggleButton)
    btnStroke.Color = Color3.fromRGB(255, 255, 255)
    btnStroke.Thickness = 1
    btnStroke.Transparency = 0.3
    
    local dragging = false
    local dragStartPos = nil
    local startButtonPos = nil
    local dragThreshold = 5
    
    ToggleButton.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            dragStartPos = input.Position
            startButtonPos = ToggleButton.Position
        end
    end)
    
    ToggleButton.InputEnded:Connect(function(input)
        if dragging then
            local delta = (input.Position - dragStartPos)
            local magnitude = math.sqrt(delta.X^2 + delta.Y^2)
            if magnitude < dragThreshold then
                MainFrame.Visible = not MainFrame.Visible
                if MainFrame.Visible then
                    MainFrame.BackgroundTransparency = 0.05
                else
                    MainFrame.BackgroundTransparency = 0.05
                end
            end
            dragging = false
            dragStartPos = nil
            startButtonPos = nil
        end
    end)
    
    UserInputService.InputChanged:Connect(function(input)
        if dragging then
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseMovement then
                local delta = input.Position - dragStartPos
                local newX = startButtonPos.X.Offset + delta.X
                local newY = startButtonPos.Y.Offset + delta.Y
                local vp = GetViewportSize()
                newX = math.clamp(newX, 0, vp.X - 55)
                newY = math.clamp(newY, 0, vp.Y - 55)
                ToggleButton.Position = UDim2.new(0, newX, 0, newY)
            end
        end
    end)
end

task.spawn(function()
    UpdateResponsiveLayout()
    local function bindCamera(cam)
        if cam then
            cam:GetPropertyChangedSignal("ViewportSize"):Connect(UpdateResponsiveLayout)
        end
    end
    if workspace.CurrentCamera then
        bindCamera(workspace.CurrentCamera)
    end
    workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        bindCamera(workspace.CurrentCamera)
        UpdateResponsiveLayout()
    end)
end)

